/* Vade Mecum — Lei 8.429/1992 — Improbidade administrativa. Texto compilado conferido no Planalto (arquivo salvo em 2026-10-31). Gerado por tools/vade-extrair.py */
(window.NEXO_VADE = window.NEXO_VADE || {})["l8429"] = {"id":"l8429","nome":"Lei 8.429/1992 — Improbidade administrativa","prefixo":"Lei 8.429/1992","titulo":"LEI Nº 8.429, DE 2 DE JUNHO DE 1992","ementa":"Dispõe sobre as sanções aplicáveis em virtude da prática de atos de improbidade administrativa, de que trata o § 4º do art. 37 da Constituição Federal; e dá outras providências.","fonte":"https://www.planalto.gov.br/ccivil_03/leis/l8429compilada.htm","extraido":"2026-10-31","itens":[{"k":"cap","t":"CAPÍTULO I","s":"Das Disposições Gerais"},{"k":"art","n":"1º","id":"a1","p":[{"k":"cap","r":"","t":"O sistema de responsabilização por atos de improbidade administrativa tutelará a probidade na organização do Estado e no exercício de suas funções, como forma de assegurar a integridade do patrimônio público e social, nos termos desta Lei.","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"Parágrafo único","t":"","n":["(Revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"par","r":"§ 1º","t":"Consideram-se atos de improbidade administrativa as condutas dolosas tipificadas nos arts. 9º, 10 e 11 desta Lei, ressalvados tipos previstos em leis especiais.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 2º","t":"Considera-se dolo a vontade livre e consciente de alcançar o resultado ilícito tipificado nos arts. 9º, 10 e 11 desta Lei, não bastando a voluntariedade do agente.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 3º","t":"O mero exercício da função ou desempenho de competências públicas, sem comprovação de ato doloso com fim ilícito, afasta a responsabilidade por ato de improbidade administrativa.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 4º","t":"Aplicam-se ao sistema da improbidade disciplinado nesta Lei os princípios constitucionais do direito administrativo sancionador.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 5º","t":"Os atos de improbidade violam a probidade na organização do Estado e no exercício de suas funções e a integridade do patrimônio público e social dos Poderes Executivo, Legislativo e Judiciário, bem como da administração direta e indireta, no âmbito da União, dos Estados, dos Municípios e do Distrito Federal.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 6º","t":"Estão sujeitos às sanções desta Lei os atos de improbidade praticados contra o patrimônio de entidade privada que receba subvenção, benefício ou incentivo, fiscal ou creditício, de entes públicos ou governamentais, previstos no § 5º deste artigo.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 7º","t":"Independentemente de integrar a administração indireta, estão sujeitos às sanções desta Lei os atos de improbidade praticados contra o patrimônio de entidade privada para cuja criação ou custeio o erário haja concorrido ou concorra no seu patrimônio ou receita atual, limitado o ressarcimento de prejuízos, nesse caso, à repercussão do ilícito sobre a contribuição dos cofres públicos.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 8º","t":"Não configura improbidade a ação ou omissão decorrente de divergência interpretativa da lei, baseada em jurisprudência, ainda que não pacificada, mesmo que não venha a ser posteriormente prevalecente nas decisões dos órgãos de controle ou dos tribunais do Poder Judiciário.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7236)","(Vide ADI 7156)"]}]},{"k":"art","n":"2º","id":"a2","p":[{"k":"cap","r":"","t":"Para os efeitos desta Lei, consideram-se agente público o agente político, o servidor público e todo aquele que exerce, ainda que transitoriamente ou sem remuneração, por eleição, nomeação, designação, contratação ou qualquer outra forma de investidura ou vínculo, mandato, cargo, emprego ou função nas entidades referidas no art. 1º desta Lei.","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"Parágrafo único","t":"No que se refere a recursos de origem pública, sujeita-se às sanções previstas nesta Lei o particular, pessoa física ou jurídica, que celebra com a administração pública convênio, contrato de repasse, contrato de gestão, termo de parceria, termo de cooperação ou ajuste administrativo equivalente.","n":["(Incluído pela Lei nº 14.230, de 2021)"]}]},{"k":"art","n":"3º","id":"a3","p":[{"k":"cap","r":"","t":"As disposições desta Lei são aplicáveis, no que couber, àquele que, mesmo não sendo agente público, induza ou concorra dolosamente para a prática do ato de improbidade.","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 1º","t":"Os sócios, os cotistas, os diretores e os colaboradores de pessoa jurídica de direito privado não respondem pelo ato de improbidade que venha a ser imputado à pessoa jurídica, salvo se, comprovadamente, houver participação e benefícios diretos, caso em que responderão nos limites da sua participação.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7156)"]},{"k":"par","r":"§ 2º","t":"As sanções desta Lei não se aplicarão à pessoa jurídica, caso o ato de improbidade administrativa seja também sancionado como ato lesivo à administração pública de que trata a Lei nº 12.846, de 1º de agosto de 2013.","n":["(Incluído pela Lei nº 14.230, de 2021)"]}]},{"k":"art","n":"4º","id":"a4","p":[{"k":"cap","r":"","t":"","n":["(Revogado pela Lei nº 14.230, de 2021)"],"rev":1}]},{"k":"art","n":"5º","id":"a5","p":[{"k":"cap","r":"","t":"","n":["(Revogado pela Lei nº 14.230, de 2021)"],"rev":1}]},{"k":"art","n":"6º","id":"a6","p":[{"k":"cap","r":"","t":"","n":["(Revogado pela Lei nº 14.230, de 2021)"],"rev":1}]},{"k":"art","n":"7º","id":"a7","p":[{"k":"cap","r":"","t":"Se houver indícios de ato de improbidade, a autoridade que conhecer dos fatos representará ao Ministério Público competente, para as providências necessárias.","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"Parágrafo único","t":"","n":["(Revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1}]},{"k":"art","n":"8º","id":"a8","p":[{"k":"cap","r":"","t":"O sucessor ou o herdeiro daquele que causar dano ao erário ou que se enriquecer ilicitamente estão sujeitos apenas à obrigação de repará-lo até o limite do valor da herança ou do patrimônio transferido.","n":["(Redação dada pela Lei nº 14.230, de 2021)"]}]},{"k":"art","n":"8º-A","id":"a8A","p":[{"k":"cap","r":"","t":"A responsabilidade sucessória de que trata o art. 8º desta Lei aplica-se também na hipótese de alteração contratual, de transformação, de incorporação, de fusão ou de cisão societária.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"Parágrafo único","t":"Nas hipóteses de fusão e de incorporação, a responsabilidade da sucessora será restrita à obrigação de reparação integral do dano causado, até o limite do patrimônio transferido, não lhe sendo aplicáveis as demais sanções previstas nesta Lei decorrentes de atos e de fatos ocorridos antes da data da fusão ou da incorporação, exceto no caso de simulação ou de evidente intuito de fraude, devidamente comprovados.","n":["(Incluído pela Lei nº 14.230, de 2021)"]}]},{"k":"cap","t":"CAPÍTULO II","s":"Dos Atos de Improbidade Administrativa"},{"k":"sec","t":"Seção I","s":"Dos Atos de Improbidade Administrativa que Importam Enriquecimento Ilícito"},{"k":"art","n":"9º","id":"a9","p":[{"k":"cap","r":"","t":"Constitui ato de improbidade administrativa importando em enriquecimento ilícito auferir, mediante a prática de ato doloso, qualquer tipo de vantagem patrimonial indevida em razão do exercício de cargo, de mandato, de função, de emprego ou de atividade nas entidades referidas no art. 1º desta Lei, e notadamente:","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"I","t":"receber, para si ou para outrem, dinheiro, bem móvel ou imóvel, ou qualquer outra vantagem econômica, direta ou indireta, a título de comissão, percentagem, gratificação ou presente de quem tenha interesse, direto ou indireto, que possa ser atingido ou amparado por ação ou omissão decorrente das atribuições do agente público;"},{"k":"inc","r":"II","t":"perceber vantagem econômica, direta ou indireta, para facilitar a aquisição, permuta ou locação de bem móvel ou imóvel, ou a contratação de serviços pelas entidades referidas no art. 1° por preço superior ao valor de mercado;"},{"k":"inc","r":"III","t":"perceber vantagem econômica, direta ou indireta, para facilitar a alienação, permuta ou locação de bem público ou o fornecimento de serviço por ente estatal por preço inferior ao valor de mercado;"},{"k":"inc","r":"IV","t":"utilizar, em obra ou serviço particular, qualquer bem móvel, de propriedade ou à disposição de qualquer das entidades referidas no art. 1º desta Lei, bem como o trabalho de servidores, de empregados ou de terceiros contratados por essas entidades;","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"V","t":"receber vantagem econômica de qualquer natureza, direta ou indireta, para tolerar a exploração ou a prática de jogos de azar, de lenocínio, de narcotráfico, de contrabando, de usura ou de qualquer outra atividade ilícita, ou aceitar promessa de tal vantagem;"},{"k":"inc","r":"VI","t":"receber vantagem econômica de qualquer natureza, direta ou indireta, para fazer declaração falsa sobre qualquer dado técnico que envolva obras públicas ou qualquer outro serviço ou sobre quantidade, peso, medida, qualidade ou característica de mercadorias ou bens fornecidos a qualquer das entidades referidas no art. 1º desta Lei;","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"VII","t":"adquirir, para si ou para outrem, no exercício de mandato, de cargo, de emprego ou de função pública, e em razão deles, bens de qualquer natureza, decorrentes dos atos descritos no caput deste artigo, cujo valor seja desproporcional à evolução do patrimônio ou à renda do agente público, assegurada a demonstração pelo agente da licitude da origem dessa evolução;","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"VIII","t":"aceitar emprego, comissão ou exercer atividade de consultoria ou assessoramento para pessoa física ou jurídica que tenha interesse suscetível de ser atingido ou amparado por ação ou omissão decorrente das atribuições do agente público, durante a atividade;"},{"k":"inc","r":"IX","t":"perceber vantagem econômica para intermediar a liberação ou aplicação de verba pública de qualquer natureza;"},{"k":"inc","r":"X","t":"receber vantagem econômica de qualquer natureza, direta ou indiretamente, para omitir ato de ofício, providência ou declaração a que esteja obrigado;"},{"k":"inc","r":"XI","t":"incorporar, por qualquer forma, ao seu patrimônio bens, rendas, verbas ou valores integrantes do acervo patrimonial das entidades mencionadas no art. 1° desta lei;"},{"k":"inc","r":"XII","t":"usar, em proveito próprio, bens, rendas, verbas ou valores integrantes do acervo patrimonial das entidades mencionadas no art. 1° desta lei."}]},{"k":"sec","t":"Seção II","s":"Dos Atos de Improbidade Administrativa que Causam Prejuízo ao Erário"},{"k":"art","n":"10","id":"a10","p":[{"k":"cap","r":"","t":"Constitui ato de improbidade administrativa que causa lesão ao erário qualquer ação ou omissão dolosa, que enseje, efetiva e comprovadamente, perda patrimonial, desvio, apropriação, malbaratamento ou dilapidação dos bens ou haveres das entidades referidas no art. 1º desta Lei, e notadamente:","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"I","t":"facilitar ou concorrer, por qualquer forma, para a indevida incorporação ao patrimônio particular, de pessoa física ou jurídica, de bens, de rendas, de verbas ou de valores integrantes do acervo patrimonial das entidades referidas no art. 1º desta Lei;","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"II","t":"permitir ou concorrer para que pessoa física ou jurídica privada utilize bens, rendas, verbas ou valores integrantes do acervo patrimonial das entidades mencionadas no art. 1º desta lei, sem a observância das formalidades legais ou regulamentares aplicáveis à espécie;"},{"k":"inc","r":"III","t":"doar à pessoa física ou jurídica bem como ao ente despersonalizado, ainda que de fins educativos ou assistências, bens, rendas, verbas ou valores do patrimônio de qualquer das entidades mencionadas no art. 1º desta lei, sem observância das formalidades legais e regulamentares aplicáveis à espécie;"},{"k":"inc","r":"IV","t":"permitir ou facilitar a alienação, permuta ou locação de bem integrante do patrimônio de qualquer das entidades referidas no art. 1º desta lei, ou ainda a prestação de serviço por parte delas, por preço inferior ao de mercado;"},{"k":"inc","r":"V","t":"permitir ou facilitar a aquisição, permuta ou locação de bem ou serviço por preço superior ao de mercado;"},{"k":"inc","r":"VI","t":"realizar operação financeira sem observância das normas legais e regulamentares ou aceitar garantia insuficiente ou inidônea;"},{"k":"inc","r":"VII","t":"conceder benefício administrativo ou fiscal sem a observância das formalidades legais ou regulamentares aplicáveis à espécie;"},{"k":"inc","r":"VIII","t":"frustrar a licitude de processo licitatório ou de processo seletivo para celebração de parcerias com entidades sem fins lucrativos, ou dispensá-los indevidamente, acarretando perda patrimonial efetiva;","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"IX","t":"ordenar ou permitir a realização de despesas não autorizadas em lei ou regulamento;"},{"k":"inc","r":"X","t":"agir ilicitamente na arrecadação de tributo ou de renda, bem como no que diz respeito à conservação do patrimônio público;","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"XI","t":"liberar verba pública sem a estrita observância das normas pertinentes ou influir de qualquer forma para a sua aplicação irregular;"},{"k":"inc","r":"XII","t":"permitir, facilitar ou concorrer para que terceiro se enriqueça ilicitamente;"},{"k":"inc","r":"XIII","t":"permitir que se utilize, em obra ou serviço particular, veículos, máquinas, equipamentos ou material de qualquer natureza, de propriedade ou à disposição de qualquer das entidades mencionadas no art. 1° desta lei, bem como o trabalho de servidor público, empregados ou terceiros contratados por essas entidades."},{"k":"inc","r":"XIV","t":"celebrar contrato ou outro instrumento que tenha por objeto a prestação de serviços públicos por meio da gestão associada sem observar as formalidades previstas na lei;","n":["(Incluído pela Lei nº 11.107, de 2005)"]},{"k":"inc","r":"XV","t":"celebrar contrato de rateio de consórcio público sem suficiente e prévia dotação orçamentária, ou sem observar as formalidades previstas na lei.","n":["(Incluído pela Lei nº 11.107, de 2005)"]},{"k":"inc","r":"XVI","t":"facilitar ou concorrer, por qualquer forma, para a incorporação, ao patrimônio particular de pessoa física ou jurídica, de bens, rendas, verbas ou valores públicos transferidos pela administração pública a entidades privadas mediante celebração de parcerias, sem a observância das formalidades legais ou regulamentares aplicáveis à espécie;","n":["(Incluído pela Lei nº 13.019, de 2014)","(Vigência)"]},{"k":"inc","r":"XVII","t":"permitir ou concorrer para que pessoa física ou jurídica privada utilize bens, rendas, verbas ou valores públicos transferidos pela administração pública a entidade privada mediante celebração de parcerias, sem a observância das formalidades legais ou regulamentares aplicáveis à espécie;","n":["(Incluído pela Lei nº 13.019, de 2014)","(Vigência)"]},{"k":"inc","r":"XVIII","t":"celebrar parcerias da administração pública com entidades privadas sem a observância das formalidades legais ou regulamentares aplicáveis à espécie;","n":["(Incluído pela Lei nº 13.019, de 2014)","(Vigência)"]},{"k":"inc","r":"XIX","t":"agir para a configuração de ilícito na celebração, na fiscalização e na análise das prestações de contas de parcerias firmadas pela administração pública com entidades privadas;","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"XX","t":"liberar recursos de parcerias firmadas pela administração pública com entidades privadas sem a estrita observância das normas pertinentes ou influir de qualquer forma para a sua aplicação irregular.","n":["(Incluído pela Lei nº 13.019, de 2014, com a redação dada pela Lei nº 13.204, de 2015)"]},{"k":"inc","r":"XXI","t":"","n":["(revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"inc","r":"XXII","t":"conceder, aplicar ou manter benefício financeiro ou tributário contrário ao que dispõem o caput e o § 1º do art. 8º-A da Lei Complementar nº 116, de 31 de julho de 2003.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 1º","t":"Nos casos em que a inobservância de formalidades legais ou regulamentares não implicar perda patrimonial efetiva, não ocorrerá imposição de ressarcimento, vedado o enriquecimento sem causa das entidades referidas no art. 1º desta Lei.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 2º","t":"A mera perda patrimonial decorrente da atividade econômica não acarretará improbidade administrativa, salvo se comprovado ato doloso praticado com essa finalidade.","n":["(Incluído pela Lei nº 14.230, de 2021)"]}]},{"k":"sec","t":"Seção II-A","s":"(Revogado pela Lei nº 14.230, de 2021)"},{"k":"art","n":"10-A","id":"a10A","p":[{"k":"cap","r":"","t":"","n":["(Revogado pela Lei nº 14.230, de 2021)"],"rev":1}]},{"k":"sec","t":"Seção III","s":"Dos Atos de Improbidade Administrativa que Atentam Contra os Princípios da Administração Pública"},{"k":"art","n":"11","id":"a11","p":[{"k":"cap","r":"","t":"Constitui ato de improbidade administrativa que atenta contra os princípios da administração pública a ação ou omissão dolosa que viole os deveres de honestidade, de imparcialidade e de legalidade, caracterizada por uma das seguintes condutas:","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"I","t":"","n":["(revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"inc","r":"II","t":"","n":["(revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"inc","r":"III","t":"revelar fato ou circunstância de que tem ciência em razão das atribuições e que deva permanecer em segredo, propiciando beneficiamento por informação privilegiada ou colocando em risco a segurança da sociedade e do Estado;","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"IV","t":"negar publicidade aos atos oficiais, exceto em razão de sua imprescindibilidade para a segurança da sociedade e do Estado ou de outras hipóteses instituídas em lei;","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"V","t":"frustrar, em ofensa à imparcialidade, o caráter concorrencial de concurso público, de chamamento ou de procedimento licitatório, com vistas à obtenção de benefício próprio, direto ou indireto, ou de terceiros;","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"VI","t":"deixar de prestar contas quando esteja obrigado a fazê-lo, desde que disponha das condições para isso, com vistas a ocultar irregularidades;","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"VII","t":"revelar ou permitir que chegue ao conhecimento de terceiro, antes da respectiva divulgação oficial, teor de medida política ou econômica capaz de afetar o preço de mercadoria, bem ou serviço."},{"k":"inc","r":"VIII","t":"descumprir as normas relativas à celebração, fiscalização e aprovação de contas de parcerias firmadas pela administração pública com entidades privadas.","n":["(Vide Medida Provisória nº 2.088-35, de 2000)","(Redação dada pela Lei nº 13.019, de 2014)","(Vigência)"]},{"k":"inc","r":"IX","t":"","n":["(revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"inc","r":"X","t":"","n":["(revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"inc","r":"XI","t":"nomear cônjuge, companheiro ou parente em linha reta, colateral ou por afinidade, até o terceiro grau, inclusive, da autoridade nomeante ou de servidor da mesma pessoa jurídica investido em cargo de direção, chefia ou assessoramento, para o exercício de cargo em comissão ou de confiança ou, ainda, de função gratificada na administração pública direta e indireta em qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios, compreendido o ajuste mediante designações recíprocas;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"XII","t":"praticar, no âmbito da administração pública e com recursos do erário, ato de publicidade que contrarie o disposto no § 1º do art. 37 da Constituição Federal, de forma a promover inequívoco enaltecimento do agente público e personalização de atos, de programas, de obras, de serviços ou de campanhas dos órgãos públicos.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 1º","t":"Nos termos da Convenção das Nações Unidas contra a Corrupção, promulgada pelo Decreto nº 5.687, de 31 de janeiro de 2006, somente haverá improbidade administrativa, na aplicação deste artigo, quando for comprovado na conduta funcional do agente público o fim de obter proveito ou benefício indevido para si ou para outra pessoa ou entidade.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 2º","t":"Aplica-se o disposto no § 1º deste artigo a quaisquer atos de improbidade administrativa tipificados nesta Lei e em leis especiais e a quaisquer outros tipos especiais de improbidade administrativa instituídos por lei.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 3º","t":"O enquadramento de conduta funcional na categoria de que trata este artigo pressupõe a demonstração objetiva da prática de ilegalidade no exercício da função pública, com a indicação das normas constitucionais, legais ou infralegais violadas.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 4º","t":"Os atos de improbidade de que trata este artigo exigem lesividade relevante ao bem jurídico tutelado para serem passíveis de sancionamento e independem do reconhecimento da produção de danos ao erário e de enriquecimento ilícito dos agentes públicos.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 5º","t":"Não se configurará improbidade a mera nomeação ou indicação política por parte dos detentores de mandatos eletivos, sendo necessária a aferição de dolo com finalidade ilícita por parte do agente.","n":["(Incluído pela Lei nº 14.230, de 2021)"]}]},{"k":"cap","t":"CAPÍTULO III","s":"Das Penas"},{"k":"art","n":"12","id":"a12","p":[{"k":"cap","r":"","t":"Independentemente do ressarcimento integral do dano patrimonial, se efetivo, e das sanções penais comuns e de responsabilidade, civis e administrativas previstas na legislação específica, está o responsável pelo ato de improbidade sujeito às seguintes cominações, que podem ser aplicadas isolada ou cumulativamente, de acordo com a gravidade do fato:","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"I","t":"na hipótese do art. 9º desta Lei, perda dos bens ou valores acrescidos ilicitamente ao patrimônio, perda da função pública, suspensão dos direitos políticos até 14 (catorze) anos, pagamento de multa civil equivalente ao valor do acréscimo patrimonial e proibição de contratar com o poder público ou de receber benefícios ou incentivos fiscais ou creditícios, direta ou indiretamente, ainda que por intermédio de pessoa jurídica da qual seja sócio majoritário, pelo prazo não superior a 14 (catorze) anos;","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"II","t":"na hipótese do art. 10 desta Lei, perda dos bens ou valores acrescidos ilicitamente ao patrimônio, se concorrer esta circunstância, perda da função pública, suspensão dos direitos políticos até 12 (doze) anos, pagamento de multa civil equivalente ao valor do dano e proibição de contratar com o poder público ou de receber benefícios ou incentivos fiscais ou creditícios, direta ou indiretamente, ainda que por intermédio de pessoa jurídica da qual seja sócio majoritário, pelo prazo não superior a 12 (doze) anos;","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"III","t":"na hipótese do art. 11 desta Lei, pagamento de multa civil de até 24 (vinte e quatro) vezes o valor da remuneração percebida pelo agente e proibição de contratar com o poder público ou de receber benefícios ou incentivos fiscais ou creditícios, direta ou indiretamente, ainda que por intermédio de pessoa jurídica da qual seja sócio majoritário, pelo prazo não superior a 4 (quatro) anos;","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"IV","t":"","n":["(revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"par","r":"Parágrafo único","t":"","n":["(Revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"par","r":"§ 1º","t":"A sanção de perda da função pública, nas hipóteses dos incisos I e II do caput deste artigo, atinge apenas o vínculo de mesma qualidade e natureza que o agente público ou político detinha com o poder público na época do cometimento da infração, podendo o magistrado, na hipótese do inciso I do caput deste artigo, e em caráter excepcional, estendê-la aos demais vínculos, consideradas as circunstâncias do caso e a gravidade da infração.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7236)","(Vide ADI 7156)"]},{"k":"par","r":"§ 2º","t":"A multa pode ser aumentada até o dobro, se o juiz considerar que, em virtude da situação econômica do réu, o valor calculado na forma dos incisos I, II e III do caput deste artigo é ineficaz para reprovação e prevenção do ato de improbidade.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 3º","t":"Na responsabilização da pessoa jurídica, deverão ser considerados os efeitos econômicos e sociais das sanções, de modo a viabilizar a manutenção de suas atividades.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 4º","t":"Em caráter excepcional e por motivos relevantes devidamente justificados, a sanção de proibição de contratação com o poder público pode extrapolar o ente público lesado pelo ato de improbidade, observados os impactos econômicos e sociais das sanções, de forma a preservar a função social da pessoa jurídica, conforme disposto no § 3º deste artigo.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7236)","(Vide ADI 7156)"]},{"k":"par","r":"§ 5º","t":"No caso de atos de menor ofensa aos bens jurídicos tutelados por esta Lei, a sanção limitar-se-á à aplicação de multa, sem prejuízo do ressarcimento do dano e da perda dos valores obtidos, quando for o caso, nos termos do caput deste artigo.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 6º","t":"Se ocorrer lesão ao patrimônio público, a reparação do dano a que se refere esta Lei deverá deduzir o ressarcimento ocorrido nas instâncias criminal, civil e administrativa que tiver por objeto os mesmos fatos.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 7º","t":"As sanções aplicadas a pessoas jurídicas com base nesta Lei e na Lei nº 12.846, de 1º de agosto de 2013, deverão observar o princípio constitucional do non bis in idem.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 8º","t":"A sanção de proibição de contratação com o poder público deverá constar do Cadastro Nacional de Empresas Inidôneas e Suspensas (CEIS) de que trata a Lei nº 12.846, de 1º de agosto de 2013, observadas as limitações territoriais contidas em decisão judicial, conforme disposto no § 4º deste artigo.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 9º","t":"As sanções previstas neste artigo somente poderão ser executadas após o trânsito em julgado da sentença condenatória.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 10","t":"Para efeitos de contagem do prazo da sanção de suspensão dos direitos políticos, computar-se-á retroativamente o intervalo de tempo entre a decisão colegiada e o trânsito em julgado da sentença condenatória.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7236)","(Vide ADI 7156)"]}]},{"k":"cap","t":"CAPÍTULO IV","s":"Da Declaração de Bens"},{"k":"art","n":"13","id":"a13","p":[{"k":"cap","r":"","t":"A posse e o exercício de agente público ficam condicionados à apresentação de declaração de imposto de renda e proventos de qualquer natureza, que tenha sido apresentada à Secretaria Especial da Receita Federal do Brasil, a fim de ser arquivada no serviço de pessoal competente.","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 1º","t":"","n":["(Revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"par","r":"§ 2º","t":"A declaração de bens a que se refere o caput deste artigo será atualizada anualmente e na data em que o agente público deixar o exercício do mandato, do cargo, do emprego ou da função.","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 3º","t":"Será apenado com a pena de demissão, sem prejuízo de outras sanções cabíveis, o agente público que se recusar a prestar a declaração dos bens a que se refere o caput deste artigo dentro do prazo determinado ou que prestar declaração falsa.","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 4º","t":"","n":["(Revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1}]},{"k":"cap","t":"CAPÍTULO V","s":"Do Procedimento Administrativo e do Processo Judicial"},{"k":"art","n":"14","id":"a14","p":[{"k":"cap","r":"","t":"Qualquer pessoa poderá representar à autoridade administrativa competente para que seja instaurada investigação destinada a apurar a prática de ato de improbidade."},{"k":"par","r":"§ 1º","t":"A representação, que será escrita ou reduzida a termo e assinada, conterá a qualificação do representante, as informações sobre o fato e sua autoria e a indicação das provas de que tenha conhecimento."},{"k":"par","r":"§ 2º","t":"A autoridade administrativa rejeitará a representação, em despacho fundamentado, se esta não contiver as formalidades estabelecidas no § 1º deste artigo. A rejeição não impede a representação ao Ministério Público, nos termos do art. 22 desta lei."},{"k":"par","r":"§ 3º","t":"Atendidos os requisitos da representação, a autoridade determinará a imediata apuração dos fatos, observada a legislação que regula o processo administrativo disciplinar aplicável ao agente.","n":["(Redação dada pela Lei nº 14.230, de 2021)"]}]},{"k":"art","n":"15","id":"a15","p":[{"k":"cap","r":"","t":"A comissão processante dará conhecimento ao Ministério Público e ao Tribunal ou Conselho de Contas da existência de procedimento administrativo para apurar a prática de ato de improbidade."},{"k":"par","r":"Parágrafo único","t":"O Ministério Público ou Tribunal ou Conselho de Contas poderá, a requerimento, designar representante para acompanhar o procedimento administrativo."}]},{"k":"art","n":"16","id":"a16","p":[{"k":"cap","r":"","t":"Na ação por improbidade administrativa poderá ser formulado, em caráter antecedente ou incidente, pedido de indisponibilidade de bens dos réus, a fim de garantir a integral recomposição do erário ou do acréscimo patrimonial resultante de enriquecimento ilícito.","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 1º","t":"","n":["(Revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"par","r":"§ 1º-A","t":"O pedido de indisponibilidade de bens a que se refere o caput deste artigo poderá ser formulado independentemente da representação de que trata o art. 7º desta Lei.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 2º","t":"Quando for o caso, o pedido de indisponibilidade de bens a que se refere o caput deste artigo incluirá a investigação, o exame e o bloqueio de bens, contas bancárias e aplicações financeiras mantidas pelo indiciado no exterior, nos termos da lei e dos tratados internacionais.","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 3º","t":"O pedido de indisponibilidade de bens a que se refere o caput deste artigo apenas será deferido mediante a demonstração no caso concreto de perigo de dano irreparável ou de risco ao resultado útil do processo, desde que o juiz se convença da probabilidade da ocorrência dos atos descritos na petição inicial com fundamento nos respectivos elementos de instrução, após a oitiva do réu em 5 (cinco) dias.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7156)"]},{"k":"par","r":"§ 4º","t":"A indisponibilidade de bens poderá ser decretada sem a oitiva prévia do réu, sempre que o contraditório prévio puder comprovadamente frustrar a efetividade da medida ou houver outras circunstâncias que recomendem a proteção liminar, não podendo a urgência ser presumida.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7156)"]},{"k":"par","r":"§ 5º","t":"Se houver mais de um réu na ação, a somatória dos valores declarados indisponíveis não poderá superar o montante indicado na petição inicial como dano ao erário ou como enriquecimento ilícito.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 6º","t":"O valor da indisponibilidade considerará a estimativa de dano indicada na petição inicial, permitida a sua substituição por caução idônea, por fiança bancária ou por seguro-garantia judicial, a requerimento do réu, bem como a sua readequação durante a instrução do processo.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 7º","t":"A indisponibilidade de bens de terceiro dependerá da demonstração da sua efetiva concorrência para os atos ilícitos apurados ou, quando se tratar de pessoa jurídica, da instauração de incidente de desconsideração da personalidade jurídica, a ser processado na forma da lei processual.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 8º","t":"Aplica-se à indisponibilidade de bens regida por esta Lei, no que for cabível, o regime da tutela provisória de urgência da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil).","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 9º","t":"Da decisão que deferir ou indeferir a medida relativa à indisponibilidade de bens caberá agravo de instrumento, nos termos da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil).","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 10","t":"A indisponibilidade recairá sobre bens que assegurem exclusivamente o integral ressarcimento do dano ao erário, sem incidir sobre os valores a serem eventualmente aplicados a título de multa civil ou sobre acréscimo patrimonial decorrente de atividade lícita.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7156)"]},{"k":"par","r":"§ 11","t":"A ordem de indisponibilidade de bens deverá priorizar veículos de via terrestre, bens imóveis, bens móveis em geral, semoventes, navios e aeronaves, ações e quotas de sociedades simples e empresárias, pedras e metais preciosos e, apenas na inexistência desses, o bloqueio de contas bancárias, de forma a garantir a subsistência do acusado e a manutenção da atividade empresária ao longo do processo.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 12","t":"O juiz, ao apreciar o pedido de indisponibilidade de bens do réu a que se refere o caput deste artigo, observará os efeitos práticos da decisão, vedada a adoção de medida capaz de acarretar prejuízo à prestação de serviços públicos.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 13","t":"É vedada a decretação de indisponibilidade da quantia de até 40 (quarenta) salários mínimos depositados em caderneta de poupança, em outras aplicações financeiras ou em conta-corrente.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 14","t":"É vedada a decretação de indisponibilidade do bem de família do réu, salvo se comprovado que o imóvel seja fruto de vantagem patrimonial indevida, conforme descrito no art. 9º desta Lei.","n":["(Incluído pela Lei nº 14.230, de 2021)"]}]},{"k":"art","n":"17","id":"a17","p":[{"k":"cap","r":"","t":"A ação para a aplicação das sanções de que trata esta Lei será proposta pelo Ministério Público e seguirá o procedimento comum previsto na Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil), salvo o disposto nesta Lei.","n":["(Redação dada pela Lei nº 14.230, de 2021)","(Vide ADI 7042)","(Vide ADI 7043)"]},{"k":"par","r":"§ 1º","t":"","n":["(Revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"par","r":"§ 2º","t":"","n":["(Revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"par","r":"§ 3º","t":"","n":["(Revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"par","r":"§ 4º","t":"","n":["(Revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"par","r":"§ 4º-A","t":"A ação a que se refere o caput deste artigo deverá ser proposta perante o foro do local onde ocorrer o dano ou da pessoa jurídica prejudicada.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 5º","t":"A propositura da ação a que se refere o caput deste artigo prevenirá a competência do juízo para todas as ações posteriormente intentadas que possuam a mesma causa de pedir ou o mesmo objeto.","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 6º","t":"A petição inicial observará o seguinte:","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"I","t":"deverá individualizar a conduta do réu e apontar os elementos probatórios mínimos que demonstrem a ocorrência das hipóteses dos arts. 9º, 10 e 11 desta Lei e de sua autoria, salvo impossibilidade devidamente fundamentada;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"II","t":"será instruída com documentos ou justificação que contenham indícios suficientes da veracidade dos fatos e do dolo imputado ou com razões fundamentadas da impossibilidade de apresentação de qualquer dessas provas, observada a legislação vigente, inclusive as disposições constantes dos arts. 77 e 80 da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil).","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 6º-A","t":"O Ministério Público poderá requerer as tutelas provisórias adequadas e necessárias, nos termos dos arts. 294 a 310 da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil)","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7042)","(Vide ADI 7043)"]},{"k":"par","r":"§ 6º-B","t":"A petição inicial será rejeitada nos casos do art. 330 da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil), bem como quando não preenchidos os requisitos a que se referem os incisos I e II do § 6º deste artigo, ou ainda quando manifestamente inexistente o ato de improbidade imputado.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 7º","t":"Se a petição inicial estiver em devida forma, o juiz mandará autuá-la e ordenará a citação dos requeridos para que a contestem no prazo comum de 30 (trinta) dias, iniciado o prazo na forma do art. 231 da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil).","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 8º","t":"","n":["(Revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"par","r":"§ 9º","t":"","n":["(Revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"par","r":"§ 9º-A","t":"Da decisão que rejeitar questões preliminares suscitadas pelo réu em sua contestação caberá agravo de instrumento.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 10","t":"","n":["(Revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"par","r":"§ 10-A","t":"Havendo a possibilidade de solução consensual, poderão as partes requerer ao juiz a interrupção do prazo para a contestação, por prazo não superior a 90 (noventa) dias.","n":["(Incluído pela Lei nº 13.964, de 2019)"]},{"k":"par","r":"§ 10-B","t":"Oferecida a contestação e, se for o caso, ouvido o autor, o juiz:","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"I","t":"procederá ao julgamento conforme o estado do processo, observada a eventual inexistência manifesta do ato de improbidade;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"II","t":"poderá desmembrar o litisconsórcio, com vistas a otimizar a instrução processual.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 10-C","t":"Após a réplica do Ministério Público, o juiz proferirá decisão na qual indicará com precisão a tipificação do ato de improbidade administrativa imputável ao réu, sendo-lhe vedado modificar o fato principal e a capitulação legal apresentada pelo autor.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7042)","(Vide ADI 7043)","(Vide ADI 7236)","(Vide ADI 7156)"]},{"k":"par","r":"§ 10-D","t":"Para cada ato de improbidade administrativa, deverá necessariamente ser indicado apenas um tipo dentre aqueles previstos nos arts. 9º, 10 e 11 desta Lei.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7236)","(Vide ADI 7156)"]},{"k":"par","r":"§ 10-E","t":"Proferida a decisão referida no § 10-C deste artigo, as partes serão intimadas a especificar as provas que pretendem produzir.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 10-F","t":"Será nula a decisão de mérito total ou parcial da ação de improbidade administrativa que:","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"I","t":"condenar o requerido por tipo diverso daquele definido na petição inicial;","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7236)","(Vide ADI 7156)"]},{"k":"inc","r":"II","t":"condenar o requerido sem a produção das provas por ele tempestivamente especificadas.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 11","t":"Em qualquer momento do processo, verificada a inexistência do ato de improbidade, o juiz julgará a demanda improcedente.","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 12","t":"","n":["(Revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"par","r":"§ 13","t":"","n":["(Revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"par","r":"§ 14","t":"Sem prejuízo da citação dos réus, a pessoa jurídica interessada será intimada para, caso queira, intervir no processo.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7042)","(Vide ADI 7043)"]},{"k":"par","r":"§ 15","t":"Se a imputação envolver a desconsideração de pessoa jurídica, serão observadas as regras previstas nos arts. 133, 134, 135, 136 e 137 da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil).","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 16","t":"A qualquer momento, se o magistrado identificar a existência de ilegalidades ou de irregularidades administrativas a serem sanadas sem que estejam presentes todos os requisitos para a imposição das sanções aos agentes incluídos no polo passivo da demanda, poderá, em decisão motivada, converter a ação de improbidade administrativa em ação civil pública, regulada pela Lei nº 7.347, de 24 de julho de 1985.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 17","t":"Da decisão que converter a ação de improbidade em ação civil pública caberá agravo de instrumento.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 18","t":"Ao réu será assegurado o direito de ser interrogado sobre os fatos de que trata a ação, e a sua recusa ou o seu silêncio não implicarão confissão.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 19","t":"Não se aplicam na ação de improbidade administrativa:","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"I","t":"a presunção de veracidade dos fatos alegados pelo autor em caso de revelia;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"II","t":"a imposição de ônus da prova ao réu, na forma dos §§ 1º e 2º do art. 373 da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil);","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7156)"]},{"k":"inc","r":"III","t":"o ajuizamento de mais de uma ação de improbidade administrativa pelo mesmo fato, competindo ao Conselho Nacional do Ministério Público dirimir conflitos de atribuições entre membros de Ministérios Públicos distintos;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"IV","t":"o reexame obrigatório da sentença de improcedência ou de extinção sem resolução de mérito.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 20","t":"A assessoria jurídica que emitiu o parecer atestando a legalidade prévia dos atos administrativos praticados pelo administrador público ficará obrigada a defendê-lo judicialmente, caso este venha a responder ação por improbidade administrativa, até que a decisão transite em julgado.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7042)","(Vide ADI 7043)"]},{"k":"par","r":"§ 21","t":"Das decisões interlocutórias caberá agravo de instrumento, inclusive da decisão que rejeitar questões preliminares suscitadas pelo réu em sua contestação.","n":["(Incluído pela Lei nº 14.230, de 2021)"]}]},{"k":"art","n":"17-A","id":"a17A","p":[{"k":"cap","r":"","t":"","n":["(VETADO)","(Incluído pela Lei nº 13.964, de 2019)"],"rev":1},{"k":"inc","r":"I","t":"","n":["(VETADO)","(Incluído pela Lei nº 13.964, de 2019)"],"rev":1},{"k":"inc","r":"II","t":"","n":["(VETADO)","(Incluído pela Lei nº 13.964, de 2019)"],"rev":1},{"k":"inc","r":"III","t":"","n":["(VETADO)","(Incluído pela Lei nº 13.964, de 2019)"],"rev":1},{"k":"par","r":"§ 1º","t":"","n":["(VETADO)","(Incluído pela Lei nº 13.964, de 2019)"],"rev":1},{"k":"par","r":"§ 2º","t":"","n":["(VETADO)","(Incluído pela Lei nº 13.964, de 2019)"],"rev":1},{"k":"par","r":"§ 3º","t":"","n":["(VETADO)","(Incluído pela Lei nº 13.964, de 2019)"],"rev":1},{"k":"par","r":"§ 4º","t":"","n":["(VETADO)","(Incluído pela Lei nº 13.964, de 2019)"],"rev":1},{"k":"par","r":"§ 5º","t":"","n":["(VETADO)","(Incluído pela Lei nº 13.964, de 2019)"],"rev":1}]},{"k":"art","n":"17-B","id":"a17B","p":[{"k":"cap","r":"","t":"O Ministério Público poderá, conforme as circunstâncias do caso concreto, celebrar acordo de não persecução civil, desde que dele advenham, ao menos, os seguintes resultados:","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7042)","(Vide ADI 7043)"]},{"k":"inc","r":"I","t":"o integral ressarcimento do dano;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"II","t":"a reversão à pessoa jurídica lesada da vantagem indevida obtida, ainda que oriunda de agentes privados.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 1º","t":"A celebração do acordo a que se refere o caput deste artigo dependerá, cumulativamente:","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"I","t":"da oitiva do ente federativo lesado, em momento anterior ou posterior à propositura da ação;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"II","t":"de aprovação, no prazo de até 60 (sessenta) dias, pelo órgão do Ministério Público competente para apreciar as promoções de arquivamento de inquéritos civis, se anterior ao ajuizamento da ação;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"III","t":"de homologação judicial, independentemente de o acordo ocorrer antes ou depois do ajuizamento da ação de improbidade administrativa.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 2º","t":"Em qualquer caso, a celebração do acordo a que se refere o caput deste artigo considerará a personalidade do agente, a natureza, as circunstâncias, a gravidade e a repercussão social do ato de improbidade, bem como as vantagens, para o interesse público, da rápida solução do caso.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 3º","t":"Para fins de apuração do valor do dano a ser ressarcido, deverá ser realizada a oitiva do Tribunal de Contas competente, que se manifestará, com indicação dos parâmetros utilizados, no prazo de 90 (noventa) dias.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7236)","(Vide ADI 7156)"]},{"k":"par","r":"§ 4º","t":"O acordo a que se refere o caput deste artigo poderá ser celebrado no curso da investigação de apuração do ilícito, no curso da ação de improbidade ou no momento da execução da sentença condenatória.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 5º","t":"As negociações para a celebração do acordo a que se refere o caput deste artigo ocorrerão entre o Ministério Público, de um lado, e, de outro, o investigado ou demandado e o seu defensor.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7042)","(Vide ADI 7043)"]},{"k":"par","r":"§ 6º","t":"O acordo a que se refere o caput deste artigo poderá contemplar a adoção de mecanismos e procedimentos internos de integridade, de auditoria e de incentivo à denúncia de irregularidades e a aplicação efetiva de códigos de ética e de conduta no âmbito da pessoa jurídica, se for o caso, bem como de outras medidas em favor do interesse público e de boas práticas administrativas.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 7º","t":"Em caso de descumprimento do acordo a que se refere o caput deste artigo, o investigado ou o demandado ficará impedido de celebrar novo acordo pelo prazo de 5 (cinco) anos, contado do conhecimento pelo Ministério Público do efetivo descumprimento.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7042)","(Vide ADI 7043)"]}]},{"k":"art","n":"17-C","id":"a17C","p":[{"k":"cap","r":"","t":"A sentença proferida nos processos a que se refere esta Lei deverá, além de observar o disposto no art. 489 da Lei nº 13.105, de 16 de março de 2015 (Código de Processo Civil):","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"I","t":"indicar de modo preciso os fundamentos que demonstram os elementos a que se referem os arts. 9º, 10 e 11 desta Lei, que não podem ser presumidos;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"II","t":"considerar as consequências práticas da decisão, sempre que decidir com base em valores jurídicos abstratos;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"III","t":"considerar os obstáculos e as dificuldades reais do gestor e as exigências das políticas públicas a seu cargo, sem prejuízo dos direitos dos administrados e das circunstâncias práticas que houverem imposto, limitado ou condicionado a ação do agente;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"IV","t":"considerar, para a aplicação das sanções, de forma isolada ou cumulativa:","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"ali","r":"a)","t":"os princípios da proporcionalidade e da razoabilidade;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"ali","r":"b)","t":"a natureza, a gravidade e o impacto da infração cometida;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"ali","r":"c)","t":"a extensão do dano causado;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"ali","r":"d)","t":"o proveito patrimonial obtido pelo agente;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"ali","r":"e)","t":"as circunstâncias agravantes ou atenuantes;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"ali","r":"f)","t":"a atuação do agente em minorar os prejuízos e as consequências advindas de sua conduta omissiva ou comissiva;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"ali","r":"g)","t":"os antecedentes do agente;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"V","t":"considerar na aplicação das sanções a dosimetria das sanções relativas ao mesmo fato já aplicadas ao agente;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"VI","t":"considerar, na fixação das penas relativamente ao terceiro, quando for o caso, a sua atuação específica, não admitida a sua responsabilização por ações ou omissões para as quais não tiver concorrido ou das quais não tiver obtido vantagens patrimoniais indevidas;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"VII","t":"indicar, na apuração da ofensa a princípios, critérios objetivos que justifiquem a imposição da sanção.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 1º","t":"A ilegalidade sem a presença de dolo que a qualifique não configura ato de improbidade.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 2º","t":"Na hipótese de litisconsórcio passivo, a condenação ocorrerá no limite da participação e dos benefícios diretos, vedada qualquer solidariedade.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7156)"]},{"k":"par","r":"§ 3º","t":"Não haverá remessa necessária nas sentenças de que trata esta Lei.","n":["(Incluído pela Lei nº 14.230, de 2021)"]}]},{"k":"art","n":"17-D","id":"a17D","p":[{"k":"cap","r":"","t":"A ação por improbidade administrativa é repressiva, de caráter sancionatório, destinada à aplicação de sanções de caráter pessoal previstas nesta Lei, e não constitui ação civil, vedado seu ajuizamento para o controle de legalidade de políticas públicas e para a proteção do patrimônio público e social, do meio ambiente e de outros interesses difusos, coletivos e individuais homogêneos.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7156)"]},{"k":"par","r":"Parágrafo único","t":"Ressalvado o disposto nesta Lei, o controle de legalidade de políticas públicas e a responsabilidade de agentes públicos, inclusive políticos, entes públicos e governamentais, por danos ao meio ambiente, ao consumidor, a bens e direitos de valor artístico, estético, histórico, turístico e paisagístico, a qualquer outro interesse difuso ou coletivo, à ordem econômica, à ordem urbanística, à honra e à dignidade de grupos raciais, étnicos ou religiosos e ao patrimônio público e social submetem-se aos termos da Lei nº 7.347, de 24 de julho de 1985.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7156)"]}]},{"k":"art","n":"18","id":"a18","p":[{"k":"cap","r":"","t":"A sentença que julgar procedente a ação fundada nos arts. 9º e 10 desta Lei condenará ao ressarcimento dos danos e à perda ou à reversão dos bens e valores ilicitamente adquiridos, conforme o caso, em favor da pessoa jurídica prejudicada pelo ilícito.","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 1º","t":"Se houver necessidade de liquidação do dano, a pessoa jurídica prejudicada procederá a essa determinação e ao ulterior procedimento para cumprimento da sentença referente ao ressarcimento do patrimônio público ou à perda ou à reversão dos bens.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 2º","t":"Caso a pessoa jurídica prejudicada não adote as providências a que se refere o § 1º deste artigo no prazo de 6 (seis) meses, contado do trânsito em julgado da sentença de procedência da ação, caberá ao Ministério Público proceder à respectiva liquidação do dano e ao cumprimento da sentença referente ao ressarcimento do patrimônio público ou à perda ou à reversão dos bens, sem prejuízo de eventual responsabilização pela omissão verificada.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 3º","t":"Para fins de apuração do valor do ressarcimento, deverão ser descontados os serviços efetivamente prestados.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 4º","t":"O juiz poderá autorizar o parcelamento, em até 48 (quarenta e oito) parcelas mensais corrigidas monetariamente, do débito resultante de condenação pela prática de improbidade administrativa se o réu demonstrar incapacidade financeira de saldá-lo de imediato.","n":["(Incluído pela Lei nº 14.230, de 2021)"]}]},{"k":"art","n":"18-A","id":"a18A","p":[{"k":"cap","r":"","t":"A requerimento do réu, na fase de cumprimento da sentença, o juiz unificará eventuais sanções aplicadas com outras já impostas em outros processos, tendo em vista a eventual continuidade de ilícito ou a prática de diversas ilicitudes, observado o seguinte:","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"I","t":"no caso de continuidade de ilícito, o juiz promoverá a maior sanção aplicada, aumentada de 1/3 (um terço), ou a soma das penas, o que for mais benéfico ao réu;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"II","t":"no caso de prática de novos atos ilícitos pelo mesmo sujeito, o juiz somará as sanções.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"Parágrafo único","t":"As sanções de suspensão de direitos políticos e de proibição de contratar ou de receber incentivos fiscais ou creditícios do poder público observarão o limite máximo de 20 (vinte) anos.","n":["(Incluído pela Lei nº 14.230, de 2021)"]}]},{"k":"cap","t":"CAPÍTULO VI","s":"Das Disposições Penais"},{"k":"art","n":"19","id":"a19","p":[{"k":"cap","r":"","t":"Constitui crime a representação por ato de improbidade contra agente público ou terceiro beneficiário, quando o autor da denúncia o sabe inocente. Pena: detenção de seis a dez meses e multa."},{"k":"par","r":"Parágrafo único","t":"Além da sanção penal, o denunciante está sujeito a indenizar o denunciado pelos danos materiais, morais ou à imagem que houver provocado."}]},{"k":"art","n":"20","id":"a20","p":[{"k":"cap","r":"","t":"A perda da função pública e a suspensão dos direitos políticos só se efetivam com o trânsito em julgado da sentença condenatória."},{"k":"par","r":"§ 1º","t":"A autoridade judicial competente poderá determinar o afastamento do agente público do exercício do cargo, do emprego ou da função, sem prejuízo da remuneração, quando a medida for necessária à instrução processual ou para evitar a iminente prática de novos ilícitos.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 2º","t":"O afastamento previsto no § 1º deste artigo será de até 90 (noventa) dias, prorrogáveis uma única vez por igual prazo, mediante decisão motivada.","n":["(Incluído pela Lei nº 14.230, de 2021)"]}]},{"k":"art","n":"21","id":"a21","p":[{"k":"cap","r":"","t":"A aplicação das sanções previstas nesta lei independe:"},{"k":"inc","r":"I","t":"da efetiva ocorrência de dano ao patrimônio público, salvo quanto à pena de ressarcimento e às condutas previstas no art. 10 desta Lei;","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"II","t":"da aprovação ou rejeição das contas pelo órgão de controle interno ou pelo Tribunal ou Conselho de Contas."},{"k":"par","r":"§ 1º","t":"Os atos do órgão de controle interno ou externo serão considerados pelo juiz quando tiverem servido de fundamento para a conduta do agente público.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 2º","t":"As provas produzidas perante os órgãos de controle e as correspondentes decisões deverão ser consideradas na formação da convicção do juiz, sem prejuízo da análise acerca do dolo na conduta do agente.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 3º","t":"As sentenças civis e penais produzirão efeitos em relação à ação de improbidade quando concluírem pela inexistência da conduta ou pela negativa da autoria.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 4º","t":"A absolvição criminal em ação que discuta os mesmos fatos, confirmada por decisão colegiada, impede o trâmite da ação da qual trata esta Lei, havendo comunicação com todos os fundamentos de absolvição previstos no art. 386 do Decreto-Lei nº 3.689, de 3 de outubro de 1941 (Código de Processo Penal).","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7236)","(Vide ADI 7156)"]},{"k":"par","r":"§ 5º","t":"Sanções eventualmente aplicadas em outras esferas deverão ser compensadas com as sanções aplicadas nos termos desta Lei.","n":["(Incluído pela Lei nº 14.230, de 2021)"]}]},{"k":"art","n":"22","id":"a22","p":[{"k":"cap","r":"","t":"Para apurar qualquer ilícito previsto nesta Lei, o Ministério Público, de ofício, a requerimento de autoridade administrativa ou mediante representação formulada de acordo com o disposto no art. 14 desta Lei, poderá instaurar inquérito civil ou procedimento investigativo assemelhado e requisitar a instauração de inquérito policial.","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"Parágrafo único","t":"Na apuração dos ilícitos previstos nesta Lei, será garantido ao investigado a oportunidade de manifestação por escrito e de juntada de documentos que comprovem suas alegações e auxiliem na elucidação dos fatos.","n":["(Incluído pela Lei nº 14.230, de 2021)"]}]},{"k":"cap","t":"CAPÍTULO VII","s":"Da Prescrição"},{"k":"art","n":"23","id":"a23","p":[{"k":"cap","r":"","t":"A ação para a aplicação das sanções previstas nesta Lei prescreve em 8 (oito) anos, contados a partir da ocorrência do fato ou, no caso de infrações permanentes, do dia em que cessou a permanência.","n":["(Redação dada pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"I","t":"","n":["(revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"inc","r":"II","t":"","n":["(revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"inc","r":"III","t":"","n":["(revogado)","(Redação dada pela Lei nº 14.230, de 2021)"],"rev":1},{"k":"par","r":"§ 1º","t":"A instauração de inquérito civil ou de processo administrativo para apuração dos ilícitos referidos nesta Lei suspende o curso do prazo prescricional por, no máximo, 180 (cento e oitenta) dias corridos, recomeçando a correr após a sua conclusão ou, caso não concluído o processo, esgotado o prazo de suspensão.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 2º","t":"O inquérito civil para apuração do ato de improbidade será concluído no prazo de 365 (trezentos e sessenta e cinco) dias corridos, prorrogável uma única vez por igual período, mediante ato fundamentado submetido à revisão da instância competente do órgão ministerial, conforme dispuser a respectiva lei orgânica.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 3º","t":"Encerrado o prazo previsto no § 2º deste artigo, a ação deverá ser proposta no prazo de 30 (trinta) dias, se não for caso de arquivamento do inquérito civil.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 4º","t":"O prazo da prescrição referido no caput deste artigo interrompe-se:","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"I","t":"pelo ajuizamento da ação de improbidade administrativa;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"II","t":"pela publicação da sentença condenatória;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"III","t":"pela publicação de decisão ou acórdão de Tribunal de Justiça ou Tribunal Regional Federal que confirma sentença condenatória ou que reforma sentença de improcedência;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"IV","t":"pela publicação de decisão ou acórdão do Superior Tribunal de Justiça que confirma acórdão condenatório ou que reforma acórdão de improcedência;","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"inc","r":"V","t":"pela publicação de decisão ou acórdão do Supremo Tribunal Federal que confirma acórdão condenatório ou que reforma acórdão de improcedência.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 5º","t":"Interrompida a prescrição, o prazo recomeça a correr do dia da interrupção, pela metade do prazo previsto no caput deste artigo.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7236)","(Vide ADI 7156)"]},{"k":"par","r":"§ 6º","t":"A suspensão e a interrupção da prescrição produzem efeitos relativamente a todos os que concorreram para a prática do ato de improbidade.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 7º","t":"Nos atos de improbidade conexos que sejam objeto do mesmo processo, a suspensão e a interrupção relativas a qualquer deles estendem-se aos demais.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 8º","t":"O juiz ou o tribunal, depois de ouvido o Ministério Público, deverá, de ofício ou a requerimento da parte interessada, reconhecer a prescrição intercorrente da pretensão sancionadora e decretá-la de imediato, caso, entre os marcos interruptivos referidos no § 4º, transcorra o prazo previsto no § 5º deste artigo.","n":["(Incluído pela Lei nº 14.230, de 2021)"]}]},{"k":"art","n":"23-A","id":"a23A","p":[{"k":"cap","r":"","t":"É dever do poder público oferecer contínua capacitação aos agentes públicos e políticos que atuem com prevenção ou repressão de atos de improbidade administrativa.","n":["(Incluído pela Lei nº 14.230, de 2021)"]}]},{"k":"art","n":"23-B","id":"a23B","p":[{"k":"cap","r":"","t":"Nas ações e nos acordos regidos por esta Lei, não haverá adiantamento de custas, de preparo, de emolumentos, de honorários periciais e de quaisquer outras despesas.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 1º","t":"No caso de procedência da ação, as custas e as demais despesas processuais serão pagas ao final.","n":["(Incluído pela Lei nº 14.230, de 2021)"]},{"k":"par","r":"§ 2º","t":"Haverá condenação em honorários sucumbenciais em caso de improcedência da ação de improbidade se comprovada má-fé.","n":["(Incluído pela Lei nº 14.230, de 2021)"]}]},{"k":"art","n":"23-C","id":"a23C","p":[{"k":"cap","r":"","t":"Atos que ensejem enriquecimento ilícito, perda patrimonial, desvio, apropriação, malbaratamento ou dilapidação de recursos públicos dos partidos políticos, ou de suas fundações, serão responsabilizados nos termos da Lei nº 9.096, de 19 de setembro de 1995.","n":["(Incluído pela Lei nº 14.230, de 2021)","(Vide ADI 7236)","(Vide ADI 7156)"]}]},{"k":"cap","t":"CAPÍTULO VIII","s":"Das Disposições Finais"},{"k":"art","n":"24","id":"a24","p":[{"k":"cap","r":"","t":"Esta lei entra em vigor na data de sua publicação."}]},{"k":"art","n":"25","id":"a25","p":[{"k":"cap","r":"","t":"Ficam revogadas as Leis n°s 3.164, de 1° de junho de 1957, e 3.502, de 21 de dezembro de 1958 e demais disposições em contrário."}]}]};
